\draw[thick] (1,0) -- (1,2) -- (5,2) -- (5,0);
\draw[dashed] (0,2) -- (1,2);
\node[below] at (1,0) {$0$};
\node[below] at (2.2,0) {$6$};
\node[below] at (3.2,0) {$11$};
\node[below] at (5,0) {$20$};
\node[left] at (0,2) {$\frac{1}{20}$};
\end{tikzpicture}
[/tikz]

