\draw[dashed] (0,2) -- (1,2);
\node[below] at (1,0) {$0$};
\node[below] at (4,0) {$18$};
\node[below] at (5,0) {$24$};
\node[left] at (0,2) {$\frac{1}{24}$};
\end{tikzpicture}
[/tikz]

questions.question_text:
A tram passes a stop at a time uniformly distributed over the $15$ minutes after a passenger arrives. Let $X$ be the wait, in minutes.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\draw[-{Stealth}] (-0.5,0) -- (6.2,0) node[right] {$x$};
\draw[-{Stealth}] (0,-0.4) -- (0,3.0) node[above] {$y$};
\draw[thick] (1,0) -- (1,2) -- (5,2) -- (5,0);
\draw[dashed] (0,2) -- (1,2);
\node[below] at (1,0) {$0$};
\node[below] at (5,0) {$15$};
\node[left] at (0,2) {$\frac{1}{15}$};
\end{tikzpicture}
[/tikz]
Find the probability that the passenger waits between $5$ and $12$ minutes.

questions.solution_text:
$P(5\le X\le 12)=\frac{12-5}{15-0}$
$=\frac{7}{15}$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}]
\fill[gray!35] (2.33,0) rectangle (4.2,2);
\draw[-{Stealth}] (-0.5,0) -- (6.2,0) node[right] {$x$};
\draw[-{Stealth}] (0,-0.4) -- (0,3.0) node[above] {$y$};
\draw[thick] (1,0) -- (1,2) -- (5,2) -- (5,0);
\draw[dashed] (0,2) -- (1,2);
\node[below] at (1,0) {$0$};
\node[below] at (2.33,0) {$5$};
\node[below] at (4.2,0) {$12$};
\node[below] at (5,0) {$15$};
\node[left] at (0,2) {$\frac{1}{15}$};
\end{tikzpicture}
[/tikz]

